    "content": "新华社科威特城10月17日电（记者尹炣）萨那消息：也门胡塞武装17日说，该组织当天击落沙特阿拉伯边境地区上空的一架“阿帕奇”武装直升机。 胡塞武装发言人叶海亚·萨雷亚在社交媒体发表声明说，这架直升机当时正在沙特奈季兰附近地区，对胡塞武装阵地实施敌对行动。 萨雷亚未透露直升机机组人员情况及事件发生的确切地点。沙特方面尚未对此作出回应。 同在17日，胡塞武装负责战俘事务的官员阿卜杜勒·穆尔塔达在萨那举行的新闻发布会上宣布，根据该组织领导层此前发布的命令，当天已在萨那释放159名在近期战斗中抓捕的政府军战俘。"
