    "content": "新华社拉姆安拉10月17日电（记者徐泽宇 赵伟宏）据巴勒斯坦通讯社17日报道，一支载有多名欧洲国家外交人员的车队当天在约旦河西岸城市拉姆安拉附近遭犹太定居者袭击。 消息人士告诉新华社记者，车队当天前往拉姆安拉以东的泰拜村途中，犹太定居者砸碎一辆载有外交人员的汽车车窗，并要求车上人员出示身份证件。 据巴勒斯坦媒体报道，法国外交官贝尔纳·博杜在袭击中受伤。 以色列军方“强烈谴责”这起袭击，称事发时没有以军士兵在场，同时表示，欧洲外交人员此次访问前未与以军协调。 巴勒斯坦副总统侯赛因·谢赫当天发表声明，谴责犹太定居者袭击…"
