    "content": "新华社巴格达10月17日电（记者李军 王泽宇）伊拉克什叶派民兵武装“人民动员组织”17日晚发布声明说，该组织位于首都巴格达一处基地内的废弃弹药堆发生爆炸，造成5人受伤。 声明说，爆炸引发的火灾已被控制，专业调查委员会已开始对事故原因及具体情况展开调查。"
