    "content": "新华社内罗毕10月17日电（记者由荟圆 马凯煜）肯尼亚卫生部17日确认，该国新增4例本迪布焦型埃博拉病例，累计确诊病例达7例，其中1例死亡。 肯尼亚卫生部发布声明称，新增病例为首例病例的1名近亲属以及曾在医院照护首例病例的3名医护人员。前者为男性，自6日起处于隔离观察状态；3名医护人员为两男一女，于3日至4日在医院照护首例病例，自9日起接受隔离，目前在指定医疗机构接受治疗。4例新增病例的首发症状都是发热。 声明说，4例新增病例在确诊时均处于隔离管控中，病毒向社区扩散的风险大大降低。目前暂无证据表明埃博拉疫情存在社区…"
