    "content": "10月17日，国务院总理李强在塔什干会见乌兹别克斯坦总统米尔济约耶夫。 新华社记者 黄敬文 摄 新华社塔什干10月17日电（记者刘畅 贺飞）10月17日，国务院总理李强在塔什干会见乌兹别克斯坦总统米尔济约耶夫。 李强表示，近年来，在习近平主席和米尔济约耶夫总统的战略引领下，中乌命运共同体建设不断取得新成果。面对国际形势变乱交织，中乌应当更加紧密团结协作，坚定携手前行。中方愿同乌方加强战略沟通，继续坚定支持彼此核心利益，拓展互利合作，为两国人民带来更多福祉。 李强指出，中方愿同乌方促进两国贸易扩大规模、优化结构，加强…"
