    "description": "10月17日下午，国务院总理李强在塔什干同乌兹别克斯坦总理阿里波夫举行会谈。新华社记者 申宏 摄 新华社塔什干10月17日电（记者贺飞 包诺敏）10月17日下午，国务院总理李强在塔什干同乌兹别克斯坦总理阿里波夫举行会谈。 李强表示，习近平主席和米尔济约耶夫总统今年8月举行会晤，为双边关系发展进一步指明方向。明年中乌将迎来建交35周年，中方愿同乌方以此为契机，赓续传统友谊，深化政治互信，加强务实合作，推动中乌命运共同体建设不断走向深入，更…",
    "content": "10月17日下午，国务院总理李强在塔什干同乌兹别克斯坦总理阿里波夫举行会谈。新华社记者 申宏 摄 新华社塔什干10月17日电（记者贺飞 包诺敏）10月17日下午，国务院总理李强在塔什干同乌兹别克斯坦总理阿里波夫举行会谈。 李强表示，习近平主席和米尔济约耶夫总统今年8月举行会晤，为双边关系发展进一步指明方向。明年中乌将迎来建交35周年，中方愿同乌方以此为契机，赓续传统友谊，深化政治互信，加强务实合作，推动中乌命运共同体建设不断走向深入，更好惠及两国人民。 李强指出，中方愿同乌方加强发展战略对接，进一步发挥经济互补优势…"
