    "content": "新华社利雅得10月17日电（记者罗晨 王海洲）沙特阿拉伯主导的多国联军发言人图尔基·马利基17日下午在社交媒体上说，联军当天在沙特利雅得省、东部省和南部地区拦截并摧毁4架无人机。 马利基当天凌晨还通报说，联军在也门萨达省摧毁两处弹道导弹发射平台。"
