    "content": "新华社东京10月17日电（记者李子越 梁晨）中国驻日本大使馆发言人17日就日本领导人向靖国神社供奉祭品、部分阁僚和国会议员前往参拜靖国神社答记者问时表示，日本二战时期发动对外侵略战争，犯下惨无人道罪行。中方强烈谴责日方涉靖国神社消极动向。 发言人表示，所谓“靖国神社”是日本军国主义的精神工具和象征，供奉有对侵略战争负有直接罪责的14名甲级战犯。日本当政者对此顶礼膜拜，无论编造何种理由，都无法隐藏其为战犯翻案、掩盖战争罪责、歪曲历史事实，为加速“再军事化”铺路的真实企图。有关错误行径是对历史正义的亵渎，对文明底线的挑…"
