    "author": "",
    "description": "10月16日，习近平总书记在内蒙古自治区乌兰察布市考察，前往察哈尔高新技术开发区，了解内蒙古自治区推进“东数西算”工程枢纽节点建设和绿色算力产业发展等情况。 对于内蒙古如何发挥独特的禀赋优势、实现转型发展，习近平总书记一直寄予厚望，强调“不能只盯着‘羊、煤、土、气’，要大力培育新产业、新动能、新增长极”“努力探索出一条以生态优先、绿色发展为导向的高质量发展新路子”。 策划：石锋、刘华 监制：吴丹 统筹：黄庆华 编导：张博令、饶力文、潘一…",
    "content": "10月16日，习近平总书记在内蒙古自治区乌兰察布市考察，前往察哈尔高新技术开发区，了解内蒙古自治区推进“东数西算”工程枢纽节点建设和绿色算力产业发展等情况。 对于内蒙古如何发挥独特的禀赋优势、实现转型发展，习近平总书记一直寄予厚望，强调“不能只盯着‘羊、煤、土、气’，要大力培育新产业、新动能、新增长极”“努力探索出一条以生态优先、绿色发展为导向的高质量发展新路子”。 策划：石锋、刘华 监制：吴丹 统筹：黄庆华 编导：张博令、饶力文、潘一景、胡碧霞 记者：黄玥、彭源 新华社新媒体中心制作 新华社第一工作室出品"
