    "content": "新华社巴格达10月17日电（记者王泽宇 李军）伊斯兰合作组织外长理事会第52次会议17日在伊拉克首都巴格达开幕。伊拉克总理扎伊迪在开幕致辞中呼吁该组织成员国加强合作、尊重差异，以促进地区稳定与和平。 据伊拉克总理新闻办公室发表的声明，扎伊迪在致辞中说，巴勒斯坦问题是地区冲突的核心，确保巴勒斯坦人民获得公正并保障其各项权利，对于实现地区安全与稳定至关重要。 伊拉克外交部17日发表的声明说，伊拉克正式接任该理事会轮值主席国。本次会议为期两天，主题为“对话与团结：促进和平与可持续发展的两大支柱”。会议将探讨一系列议题，重…"
