    "content": "北部湾潮涌，边海生机勃发。10月17日，记者跟随“活力中国调研行”采访团沿着北部湾畔的临港工业带一路前行，在广西钢铁集团（柳钢防城港基地），见证传统钢铁产业转型升级的向新路径；在防城港国际医学开放试验区，感受本土医药扬帆出海的开放脉动。两处现场，串联起传统产业智能化升级与新兴产业国际化开拓的两条发展脉络，展现广西的开放活力。 走进柳钢防城港基地冷轧厂，首先映入眼帘的是成排摆放整齐的钢卷，无人天车正在有条不紊地搬运经过冷轧加工后的钢卷，连续退火生产线车间内只有机器运行的声音，一改钢铁行业“凭经验、靠人力”的传统印象。…"
