    "title": "微信鸿蒙版上线小艺语音操作：一句话即可发消息、打语音和视频",
    "link": "https://36kr.com/newsflashes/4029995773317766?f=rss",
    "pub_date": "2026-10-17 21:23:41",
    "author": "",
    "description": "近日，微信鸿蒙版已上线小艺语音操作能力。唤醒小艺后，直接说“用微信给XX发消息”“给XX打微信语音”或“给XX打微信视频”，即可完成对应操作，发送消息还可直接说出具体内容。如遇联系人重名或指令不清，小艺会提示确认。开车、做饭、做家务等不便使用双手时，沟通更加简单直接。更新微信鸿蒙版和小艺至最新版本即可体验。",
    "content": "近日，微信鸿蒙版已上线小艺语音操作能力。唤醒小艺后，直接说“用微信给XX发消息”“给XX打微信语音”或“给XX打微信视频”，即可完成对应操作，发送消息还可直接说出具体内容。如遇联系人重名或指令不清，小艺会提示确认。开车、做饭、做家务等不便使用双手时，沟通更加简单直接。更新微信鸿蒙版和小艺至最新版本即可体验。"
