    "author": "全灿",
    "description": "新华社德黑兰10月17日电 伊朗伊斯兰革命卫队海军17日在社交媒体发表声明说，“第二艘超级油轮”当天在霍尔木兹海峡触雷后发生剧烈爆炸并起火。 声明说，该油轮载有超过200万桶原油，在关闭所有导航和雷达系统后，试图在美军的支持下通过霍尔木兹海峡。 伊朗革命卫队海军17日早些时候发表声明说，一艘超级油轮在霍尔木兹海峡触雷后发生爆炸并起火。声明还再次强调，“霍尔木兹海峡已关闭”。",
    "content": "新华社德黑兰10月17日电 伊朗伊斯兰革命卫队海军17日在社交媒体发表声明说，“第二艘超级油轮”当天在霍尔木兹海峡触雷后发生剧烈爆炸并起火。 声明说，该油轮载有超过200万桶原油，在关闭所有导航和雷达系统后，试图在美军的支持下通过霍尔木兹海峡。 伊朗革命卫队海军17日早些时候发表声明说，一艘超级油轮在霍尔木兹海峡触雷后发生爆炸并起火。声明还再次强调，“霍尔木兹海峡已关闭”。"
