    "content": "新华社东京10月17日电（记者李子越 陈泽安）据日本共同社17日报道，日本政府正考虑通过进一步提高企业的法人税，为预计将持续膨胀的防卫费筹措资金。媒体称有关计划可能引发经济界反对。 报道说，日本政府正在推进“安保三文件”修订，其中，新一轮覆盖2027至2031财年的《防卫力整备计划》提出大量采购无人机、增加弹药和导弹储备，为长期作战做准备。报道援引日本政府高层人士的话称，如果按照防卫省所需进行估算，未来5年日本防卫费总额“可能膨胀至70万亿至80万亿日元（1美元约合158日元）”。 报道援引多名相关人士消息称，面对…"
