    "content": "湘江战役，是红军长征中的悲壮一幕。 2014年10月，在福建古田召开的全军政治工作会议上，习近平总书记讲述了陈树湘“断肠明志”的故事。总书记说，闽西这个地方为革命作出过突出贡献。长征出发时，红军中有两万多闽西儿女。担任中央红军总后卫的红34师，6000多人主要是闽西子弟，湘江一战几乎全师牺牲。师长陈树湘不幸被俘，他撕开腹部伤口，绞断肠子，壮烈牺牲，实现了“为苏维埃流尽最后一滴血”的誓言。 2021年4月，习近平总书记来到位于广西桂林全州县才湾镇的红军长征湘江战役纪念园，向湘江战役红军烈士敬献花篮，参观红军长征湘江战…"
