    "content": "新华社塔什干10月17日电(记者董雪 郑钰)10月17日上午，应乌兹别克斯坦总理阿里波夫邀请，国务院总理李强乘包机离开北京，对乌兹别克斯坦进行正式访问。国务委员兼国务院秘书长吴政隆等陪同人员同机离京。"
