    "author": "国内部",
    "description": "10月17日上午，国务院总理李强在北京出席2026世界传统医药大会开幕式并致辞。新华社记者 黄敬文 摄 新华社北京10月17日电 10月17日上午，国务院总理李强在北京出席2026世界传统医药大会开幕式并致辞。 李强表示，正如习近平主席在致2024世界传统医药大会的贺信中指出，传统医药是人类文明创造的成果，需要代代守护、传承精华，也需要与时俱进、守正创新。当今时代，传统医药应当如何更好发挥自身作用？结合中国传统医药发展实践，我同大家分享…",
    "content": "10月17日上午，国务院总理李强在北京出席2026世界传统医药大会开幕式并致辞。新华社记者 黄敬文 摄 新华社北京10月17日电 10月17日上午，国务院总理李强在北京出席2026世界传统医药大会开幕式并致辞。 李强表示，正如习近平主席在致2024世界传统医药大会的贺信中指出，传统医药是人类文明创造的成果，需要代代守护、传承精华，也需要与时俱进、守正创新。当今时代，传统医药应当如何更好发挥自身作用？结合中国传统医药发展实践，我同大家分享一些体会和思考。 第一，传统医药是守护人类健康和推动文明进步的独特力量。传统医药…"
