    "author": "张兆卿,张馨文,康逸",
    "description": "新华社布鲁塞尔10月17日电（记者张兆卿 张馨文 康逸）为期两天的欧盟峰会16日在比利时首都布鲁塞尔落幕。欧盟成员国仍未就长期预算达成一致，各方还围绕能源政策激烈争论。乌克兰要求追加700亿欧元援助令欧盟进一步承压。 媒体和分析人士认为，此次峰会实质性成果有限。欧盟成员国之间的分歧叠加跨大西洋关系变化，让欧盟越发理不清财政、能源和安全“三本账”，其眼下处境可谓难上加难。 “财政账”：长期预算难协调 欧盟2028年至2034年长期预算是此…",
    "content": "新华社布鲁塞尔10月17日电（记者张兆卿 张馨文 康逸）为期两天的欧盟峰会16日在比利时首都布鲁塞尔落幕。欧盟成员国仍未就长期预算达成一致，各方还围绕能源政策激烈争论。乌克兰要求追加700亿欧元援助令欧盟进一步承压。 媒体和分析人士认为，此次峰会实质性成果有限。欧盟成员国之间的分歧叠加跨大西洋关系变化，让欧盟越发理不清财政、能源和安全“三本账”，其眼下处境可谓难上加难。 “财政账”：长期预算难协调 欧盟2028年至2034年长期预算是此次峰会的重要议题。不过，各成员国在预算规模等关键点上存在明显分歧。 “过于庞大，…"
