    "content": "新华社东京10月17日电（记者李子越 梁晨）据日本共同社报道，日本自民党政务调查会长小林鹰之17日参拜靖国神社。 当天早些时候，日本媒体称日本首相高市早苗以“内阁总理大臣”名义，向靖国神社供奉名为“真榊”的祭品，包括日本众议院议长森英介、参议院议长关口昌一在内的多名政客也向靖国神社供奉了“真榊”祭品。此外，日本经济财政政策担当大臣城内实当天上午也参拜了靖国神社。 靖国神社17日起举行为期3天的秋季大祭。靖国神社位于东京千代田区，神社内供奉有包括东条英机在内的14名二战甲级战犯。长期以来，日本部分政客、国会议员坚持参…"
