    "content": "新华社利雅得10月17日电 热点问答｜沙特与胡塞武装冲突为何僵持不下 新华社记者王海洲 罗晨 连日来，沙特阿拉伯主导的多国联军同也门胡塞武装持续相互袭击，地区冲突进一步升级。沙特联军对也门多地发动频繁空袭，胡塞武装则持续向沙特境内机场和石油设施发动打击，造成设施损毁和人员伤亡。近期冲突战况如何？双方为何僵持不下？未来局势会怎样发展？ 近期战况如何 沙特主导的多国联军发言人图尔基·马利基15日在利雅得举行的新闻发布会上说，10月以来，胡塞武装对哈立德国王国际机场实施20次袭击，造成17人死亡、333人受伤。胡塞武装1…"
