    "content": "新华社济南10月17日电 题：山东深耕垂域大模型赋能实体产业 新华社记者陈国峰、张昕怡 操控室里，大屏上的参数实时跳动；生产线上，通红的钢坯自动完成轧制。在山东钢铁集团日照有限公司，山鼎云科研发的尚智冶金AI大模型为钢铁生产装上了“智慧大脑”。 “尚智大模型已支撑智能配矿、自动转钢、安全监测等40多个工业场景。”山鼎云科人工智能研究院技术总监杨龙说，大模型的应用提升了轧钢成材率，降低了冶炼能耗，吨钢综合生产成本降低3至6元。 从车间到会场，人工智能大模型正在齐鲁大地积蓄新动能。10月14日至16日，2026人工智能…"
