    "content": "新华社武汉10月17日电 题：在武网，看见中国网球的百花齐放 新华社记者乐文婉、余熙 16日晚，随着女双组合郭涵煜/梅拉德诺维奇、张帅/达尼丽娜无缘四强，本届武网的中国队选手全部出局，女单最佳成绩是郭涵煜拼下的16强，女双最佳成绩是郭涵煜、张帅与各自搭档取得的八强。 时间回拨至一周前，很多人可能想不到坚守到最后的中国球员会是她们。武网正赛开打当天，刚在中国网球公开赛捧起冠军奖杯的郑钦文宣布因右肩受伤退出家乡赛事，不少球迷感到遗憾。但“巨星”缺席的武网，惊喜地让人看到中国网球的百花齐放。 10月12日，演员在开幕仪式…"
